<?php
require_once __DIR__ . '/_vault_helpers.php'; require_once __DIR__ . '/../helpers/EmailHelper.php';
try { $db=vault_db(); $actor=vault_require_auth(); $d=vault_input(); vault_require_csrf($d); vault_require_verified(); $id=(int)($d['document_id']??0); $doc=vault_require_document_access($db,$id,$actor); $s=$db->prepare("SELECT email,full_name FROM users WHERE id=:id AND status='active' LIMIT 1"); $s->execute(['id'=>$actor]); $user=$s->fetch(PDO::FETCH_ASSOC); if(!$user||!filter_var($user['email'],FILTER_VALIDATE_EMAIL)){ApiResponse::serverError('A verified account email is required.');exit;} $code=EmailHelper::generateVerificationCode(); $_SESSION['vault_download_challenge']=['actor'=>$actor,'document_id'=>$id,'hash'=>password_hash($code,PASSWORD_DEFAULT),'expires'=>time()+600,'attempts'=>0]; if(!EmailHelper::sendVaultDownloadCode($user['email'],$user['full_name'],$code,$doc['display_name'])){unset($_SESSION['vault_download_challenge']);ApiResponse::serverError('Unable to send verification code.');exit;} vault_log($db,(int)$doc['owner_id'],$actor,$id,'download_code_sent'); ApiResponse::success([],'Verification code sent to your email.'); } catch(Throwable $e){Logger::error('Vault download code failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to start secure download.');}